"""Write import blocks and prepare backed-up export destinations."""
import datetime as dt
import shutil
import sys
import re
import json
from pathlib import Path


def hcl_string(value):
    return json.dumps(str(value).replace('${', '$${').replace('%{', '%%{'), ensure_ascii=False)


def indexed(resource, key):
    return f'{resource}[{hcl_string(key)}]'


def write_imports(path, imports, bindings=None):
    lines = [
        "# Generated by scripts/export_zone.py.",
        "# These blocks tell Terraform to ADOPT objects that already exist in",
        "# Cloudflare instead of creating them; the change summary lists them",
        "# as \"adopt\". Delete this file after the first successful apply.",
        "",
    ]
    for to, id_ in imports:
        resource_type = re.findall(r'(cloudflare_[a-z_]+)\.', to)[-1]
        previous = (bindings or {}).get(f"{resource_type}|{id_}")
        if previous and previous != to:
            # State addresses contain literal JSON keys; HCL interprets ${...}.
            source = re.sub(r'"(?:\\.|[^"\\])*"', lambda match: hcl_string(json.loads(match[0])), previous)
            lines += ["moved {", f"  from = {source}", f"  to = {to}", "}", ""]
        lines += ["import {", f"  to = {to}", f'  id = {hcl_string(id_)}', "}", ""]
    Path(path).write_text("\n".join(lines), encoding="utf-8", newline="\n")


def prepare_dest(dest, force, backup_dir):
    if not dest.exists():
        return
    if not force:
        sys.exit(f"{dest} already exists. Re-run with --force to replace it "
                 f"(the current folder is backed up to {backup_dir} first).")
    stamp = dt.datetime.now().strftime("%Y%m%d-%H%M%S")
    shutil.copytree(dest, backup_dir / f"backup-{stamp}")
    shutil.rmtree(dest)
    print(f"Backed up the old folder to {backup_dir / f'backup-{stamp}'}")
